// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MergingPool} from "../src/MergingPool.sol";

contract InvMutTest is Test {
    MergingPool c;
    function setUp() public { c = new MergingPool(address(this), address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(address actor, uint256 newAmount) public {
        vm.assume(actor != address(this));
        uint256 before = c.winnersPerPeriod();

        vm.prank(actor);
        try c.updateWinnersPerPeriod(newAmount) {
            // non-admin caller must NOT be able to update winnersPerPeriod
            assertTrue(false, "non-admin changed winnersPerPeriod");
        } catch {
            assertTrue(c.winnersPerPeriod() == before, "winnersPerPeriod changed by non-admin");
        }
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
